import {getAudioEngine} from './audio-engine.js';
import {winterTracks} from './music-catalog.js';
export {winterTracks,winterTrack} from './music-catalog.js';
export function createWinterMusic(doc=document,win=window){
 const engine=getAudioEngine(win),$=s=>doc.querySelector(s),select=$('#music-select'),label=$('#music-track'),button=$('#music'),players=[0,1].map(()=>{const a=doc.createElement('audio');a.preload='none';a.hidden=true;a.loop=false;doc.body.append(a);engine.registerMedia(a);return a;});
 let index=0,current=0,started=false,requestId=0,fadeTimer=null,fading=false,shuffle=false,repeat=true,lastVolume=engine.state.music;const history=[];let bag=[];
 try{index=Math.max(0,winterTracks.findIndex(t=>t.id===win.localStorage.getItem('lab-music-track')));shuffle=win.localStorage.getItem('winter-music-shuffle')==='on';repeat=win.localStorage.getItem('winter-music-repeat')!=='off';}catch{}
 players[0].id='winter-background-music';players[0].src=winterTracks[index].src;engine.fadeMedia(players[0],1);engine.fadeMedia(players[1],0);
 select.replaceChildren();for(const t of winterTracks){const option=doc.createElement('option');option.value=t.id;option.textContent=t.title;select.append(option);}
 function labels(){const t=winterTracks[index];label.textContent=t.title+' · '+t.artist;select.value=t.id;select.dispatchEvent(new doc.defaultView.Event('lab:select-sync'));$('#music-source').href=t.source;$('#music-source').textContent=t.title+' — '+t.artist;$('#music-license').href=t.license;$('#music-license').textContent=t.licenseName;$('#music-count').textContent=winterTracks.length+'곡';$('#music-shuffle').setAttribute('aria-pressed',shuffle);$('#music-repeat').setAttribute('aria-pressed',repeat);}
 function save(){try{win.localStorage.setItem('lab-music-track',winterTracks[index].id);win.localStorage.setItem('winter-music-shuffle',shuffle?'on':'off');win.localStorage.setItem('winter-music-repeat',repeat?'on':'off');}catch{}}
 function cancelFade(){win.clearTimeout(fadeTimer);fading=false;for(let i=0;i<2;i++){engine.fadeMedia(players[i],i===current?1:0);if(i!==current)players[i].pause();}}
 async function play(){if(!engine.state.musicEnabled||doc.hidden||!players[current].paused)return;engine.unlock();const token=++requestId;try{await players[current].play();if(token===requestId){started=true;labels();}}catch{if(token===requestId)label.textContent='재생 버튼을 눌러 주세요.';}}
 async function choose(next,remember=true){if(next<0||next>=winterTracks.length)return;const token=++requestId;cancelFade();const previous=current,slot=1-current,a=players[slot];a.pause();a.src=winterTracks[next].src;engine.fadeMedia(a,0);if(remember&&index!==next)history.push(index);if(history.length>30)history.shift();
  if(!engine.state.musicEnabled||!started){index=next;current=slot;players[previous].pause();engine.fadeMedia(a,1);labels();save();if(started&&engine.state.musicEnabled)play();return;}
  try{await a.play();if(token!==requestId){a.pause();return;}current=slot;index=next;started=true;fading=true;players[previous].id='winter-background-tail';a.id='winter-background-music';engine.fadeMedia(a,1,2.5);engine.fadeMedia(players[previous],0,2.5);labels();save();fadeTimer=win.setTimeout(()=>{if(token===requestId){players[previous].pause();fading=false;}},2600);}catch{if(token===requestId)label.textContent='음원을 불러오지 못했습니다. 다음 곡을 눌러 주세요.';}
 }
 function next(){if(shuffle){if(!bag.length){bag=winterTracks.map((_,i)=>i).filter(i=>i!==index);for(let i=bag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]];}}choose(bag.shift()??index);}else if(index===winterTracks.length-1&&!repeat)engine.settings({musicEnabled:false});else choose((index+1)%winterTracks.length);}
 select.addEventListener('change',()=>{started=true;engine.unlock();choose(winterTracks.findIndex(t=>t.id===select.value));});$('#music-next').addEventListener('click',()=>{started=true;engine.unlock();next();});$('#music-prev').addEventListener('click',()=>{started=true;engine.unlock();choose(history.pop()??(index+winterTracks.length-1)%winterTracks.length,false);});
 for(const a of players){a.addEventListener('timeupdate',()=>{if(a===players[current]&&!fading&&engine.state.musicEnabled&&Number.isFinite(a.duration)&&a.duration>8&&a.duration-a.currentTime<2.5)next();});a.addEventListener('ended',()=>{if(a===players[current]&&!fading)next();});a.addEventListener('error',()=>{if(a===players[current])label.textContent='음원을 불러오지 못했습니다. 다음 곡을 눌러 주세요.';});}
 button.addEventListener('click',()=>{engine.settings({musicEnabled:!engine.state.musicEnabled});if(engine.state.musicEnabled)play();});
 $('#music-shuffle').onclick=()=>{shuffle=!shuffle;bag=[];labels();save();};$('#music-repeat').onclick=()=>{repeat=!repeat;labels();save();};$('#music-mute').onclick=()=>{const s=engine.state;if(s.music>0){lastVolume=s.music;engine.settings({music:0});}else engine.settings({music:lastVolume||.75});};
 const sliders=[['master-volume','master-value','master'],['music-volume','music-value','music'],['ambient-volume','ambient-value','ambient'],['sound-volume','volume-value','effects']];for(const [id,,key]of sliders)$('#'+id).addEventListener('input',e=>engine.settings({[key]:Number(e.target.value)/100}));
 $('#master-mute').onclick=()=>engine.settings({muted:!engine.state.muted});$('#ambient').onclick=()=>engine.settings({ambientEnabled:!engine.state.ambientEnabled});$('#sound').onclick=()=>engine.settings({effectsEnabled:!engine.state.effectsEnabled});
 engine.subscribe(state=>{for(const [id,output,key]of sliders){$('#'+id).value=Math.round(state[key]*100);$('#'+output).textContent=Math.round(state[key]*100)+'%';}for(const [id,key]of [['music','musicEnabled'],['ambient','ambientEnabled'],['sound','effectsEnabled']]){$('#'+id).textContent=state[key]?'켜짐':'꺼짐';$('#'+id).setAttribute('aria-checked',state[key]);}$('#master-mute').setAttribute('aria-pressed',state.muted);$('#master-mute').textContent=state.muted?'전체 음소거 해제':'전체 음소거';$('#music-mute').setAttribute('aria-pressed',state.music===0);if(!state.musicEnabled){requestId++;cancelFade();for(const a of players)a.pause();}if(!engine.context)engine.fadeMedia(players[current],1);});
 doc.addEventListener('pointerdown',play,{capture:true});doc.addEventListener('keydown',play,{capture:true});doc.addEventListener('visibilitychange',()=>{if(doc.hidden){requestId++;cancelFade();for(const a of players)a.pause();}else if(started)play();});win.addEventListener('pagehide',()=>{requestId++;cancelFade();players.forEach(a=>a.pause());});labels();
 return{get enabled(){return engine.state.musicEnabled},get track(){return winterTracks[index]},get audio(){return players[current]},engine};
}
if(typeof document!=='undefined'&&document.querySelector('#music'))createWinterMusic();
